using System;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using Xunit;
namespace RPCore.Tests
{
    public class CustodyTests
    {
        static CustodyOptions Options()=>CustodyOptions.Defaults();
        static WalletData Book(int stars=2){var w=new WalletData{Cash=777,Bank=10000};Assert.True(CustodyTransactions.Configure(w,true,()=>{},out _));Assert.True(CustodyTransactions.Book(w,"case",stars,Options(),()=>{},out _));return w;}
        [Fact] public void OldWalletDoesNotOptInAndUnknownFieldsRoundTrip(){var w=JsonConvert.DeserializeObject<WalletData>("{\"Bank\":500,\"Future\":42}");Assert.Null(w.Custody);Assert.False(CustodyTransactions.Book(w,"x",1,Options(),()=>throw new Exception(),out _));Assert.Null(w.Custody);Assert.Equal(42,(int)w.Extra["Future"]);}
        [Theory] [InlineData(1)] [InlineData(2)] [InlineData(3)] [InlineData(4)] [InlineData(5)]
        public void SentenceAndBailSnapshotStarsWithoutCharging(int stars){var w=Book(stars);Assert.True(w.Custody.Valid);Assert.Equal(stars*60000,w.Custody.Pending.RemainingMilliseconds);Assert.Equal(stars*500,w.Custody.Pending.Bail);Assert.Equal(10000,w.Bank);Assert.Equal(777,w.Cash);Assert.Equal(1,w.Custody.Booked);}
        [Theory] [InlineData(-1)] [InlineData(0)] [InlineData(6)] [InlineData(int.MaxValue)]
        public void InvalidStarsCannotCreateOrDebit(int stars){var w=Book();string before=JsonConvert.SerializeObject(w);Assert.False(CustodyTransactions.Book(w,"new",stars,Options(),()=>throw new Exception(),out _));Assert.Equal(before,JsonConvert.SerializeObject(w));}
        [Fact] public void PendingCannotBeOverwrittenOrDisabled(){var w=Book();Assert.False(CustodyTransactions.Book(w,"other",1,Options(),()=>throw new Exception(),out _));Assert.False(CustodyTransactions.Configure(w,false,()=>throw new Exception(),out _));Assert.Equal("case",w.Custody.Pending.Id);}
        [Fact] public void SnapshotIsDetachedFromConfigurationAndRetainsMetadata(){var w=new WalletData{Bank=100};CustodyTransactions.Configure(w,true,()=>{},out _);var c=Options();c.Extra=new System.Collections.Generic.Dictionary<string,JToken>{{"Future",123}};Assert.True(CustodyTransactions.Book(w,"a",1,c,()=>{},out _));c.SecondsPerStar=600;c.Cell.X=100;Assert.Equal(60,w.Custody.Pending.Options.SecondsPerStar);Assert.Equal(459.85f,w.Custody.Pending.Options.Cell.X);Assert.Equal(123,(int)w.Custody.Pending.Options.Extra["Future"]);}
        [Fact] public void CheckpointIsAbsoluteMonotoneAndIdempotentAcrossReload(){var w=Book();int saves=0;Assert.True(CustodyTransactions.Checkpoint(w,"case",115000,()=>saves++,out bool changed));Assert.True(changed);w=JsonConvert.DeserializeObject<WalletData>(JsonConvert.SerializeObject(w));Assert.True(CustodyTransactions.Checkpoint(w,"case",115000,()=>throw new Exception(),out changed));Assert.False(changed);Assert.False(CustodyTransactions.Checkpoint(w,"case",120000,()=>throw new Exception(),out _));Assert.Equal(115000,w.Custody.Pending.RemainingMilliseconds);Assert.Equal(1,saves);}
        [Theory] [InlineData(null,1000)] [InlineData("wrong",1000)] [InlineData("case",-1)] [InlineData("case",120001)]
        public void BadCheckpointCannotConsumeTime(string id,int time){var w=Book();Assert.False(CustodyTransactions.Checkpoint(w,id,time,()=>throw new Exception(),out _));Assert.Equal(120000,w.Custody.Pending.RemainingMilliseconds);}
        [Fact] public void MissingPendingCheckpointIsRejectedWithoutNullDereference(){var w=Book();CustodyTransactions.Release(w,"case",true,()=>{},out _);Assert.False(CustodyTransactions.Checkpoint(w,null,0,()=>throw new Exception(),out _));}
        [Fact] public void FreeReleaseRequiresWholeSentenceAndPaysNothing(){var w=Book();Assert.False(CustodyTransactions.Release(w,"case",false,()=>throw new Exception(),out _));CustodyTransactions.Checkpoint(w,"case",0,()=>{},out _);Assert.True(CustodyTransactions.Release(w,"case",false,()=>{},out bool changed));Assert.True(changed);Assert.Null(w.Custody.Pending);Assert.Equal(1,w.Custody.Served);Assert.Equal(10000,w.Bank);Assert.Equal(777,w.Cash);Assert.True(w.Custody.Valid);Assert.True(CustodyTransactions.Release(w,"case",false,()=>throw new Exception(),out changed));Assert.False(changed);Assert.False(CustodyTransactions.Release(w,"case",true,()=>throw new Exception(),out _));}
        [Fact] public void BailUsesExactBankDebitOnceAndLeavesTrafficDebt(){var w=Book();w.Traffic=new TrafficData();string traffic=JsonConvert.SerializeObject(w.Traffic);Assert.True(CustodyTransactions.Release(w,"case",true,()=>{},out _));Assert.Equal(9000,w.Bank);Assert.Equal(777,w.Cash);Assert.Equal(1000,w.Custody.BailPaid);Assert.Equal(1,w.Custody.Bailed);w=JsonConvert.DeserializeObject<WalletData>(JsonConvert.SerializeObject(w));Assert.True(CustodyTransactions.Release(w,"case",true,()=>throw new Exception(),out bool changed));Assert.False(changed);Assert.Equal(9000,w.Bank);Assert.Equal(traffic,JsonConvert.SerializeObject(w.Traffic));}
        [Fact] public void InsufficientBankNeverPartiallyChargesOrUsesCash(){var w=Book();w.Bank=999;w.Cash=100000;string before=JsonConvert.SerializeObject(w);Assert.False(CustodyTransactions.Release(w,"case",true,()=>throw new Exception(),out _));Assert.Equal(before,JsonConvert.SerializeObject(w));}
        [Theory] [InlineData("configure")] [InlineData("book")] [InlineData("checkpoint")] [InlineData("bail")] [InlineData("serve")]
        public void EverySaveFailureRollsBackWholeTransaction(string step){var w=step=="configure"?new WalletData{Bank=10000}:Book();if(step=="book")CustodyTransactions.Release(w,"case",true,()=>{},out _);if(step=="serve")CustodyTransactions.Checkpoint(w,"case",0,()=>{},out _);string before=JsonConvert.SerializeObject(w);Action fail=()=>throw new InvalidOperationException();Assert.Throws<InvalidOperationException>(()=>{if(step=="configure")CustodyTransactions.Configure(w,true,fail,out _);if(step=="book")CustodyTransactions.Book(w,"new",1,Options(),fail,out _);if(step=="checkpoint")CustodyTransactions.Checkpoint(w,"case",1000,fail,out _);if(step=="bail")CustodyTransactions.Release(w,"case",true,fail,out _);if(step=="serve")CustodyTransactions.Release(w,"case",false,fail,out _);});Assert.Equal(before,JsonConvert.SerializeObject(w));}
        [Fact] public void BoundedHistoryKeepsLifetimeTotalsAndMetadata(){var w=Book(1);w.Custody.Extra=new System.Collections.Generic.Dictionary<string,JToken>{{"Future","keep"}};for(int i=0;i<40;i++){string id=w.Custody.Pending.Id;CustodyTransactions.Checkpoint(w,id,0,()=>{},out _);Assert.True(CustodyTransactions.Release(w,id,false,()=>{},out _));if(i<39)Assert.True(CustodyTransactions.Book(w,"case"+i,1,Options(),()=>{},out _));}Assert.Equal(32,w.Custody.History.Count);Assert.Equal(40,w.Custody.Served);Assert.Equal(40,w.Custody.Booked);Assert.Equal("keep",(string)w.Custody.Extra["Future"]);Assert.True(w.Custody.Valid);}
        [Fact] public void MalformedHistoryOrPendingIsProtected(){var w=Book();w.Custody.History=null;Assert.False(w.Custody.Valid);Assert.False(CustodyTransactions.Configure(w,true,()=>throw new Exception(),out _));w.Custody.History=new System.Collections.Generic.List<CustodyCase>();w.Custody.Pending.RemainingMilliseconds=-1;Assert.False(w.Custody.Valid);Assert.False(CustodyTransactions.Release(w,"case",true,()=>throw new Exception(),out _));}
        [Fact] public void OverflowDoesNotCharge(){var w=Book();w.Custody.BailPaid=long.MaxValue;Assert.True(w.Custody.Valid);Assert.False(CustodyTransactions.Release(w,"case",true,()=>throw new Exception(),out _));Assert.Equal(10000,w.Bank);}
        [Theory] [InlineData(16,true,16)] [InlineData(1000,true,1000)] [InlineData(1001,true,0)] [InlineData(-1,true,0)] [InlineData(500,false,0)] [InlineData(int.MaxValue,true,0)]
        public void OnlyActiveNonStalledTimeCounts(int delta,bool eligible,int expected){Assert.Equal(expected,CustodyRules.Credit(delta,eligible));}
        [Fact] public void SurrenderNeedsWantedStationaryUnarmedFootPlayerAndActualWitness(){Assert.True(CustodyRules.Surrender(true,true,true,true,false,false,false,2,0,true));Assert.False(CustodyRules.Surrender(true,true,true,true,false,false,false,0,0,true));Assert.False(CustodyRules.Surrender(true,true,true,true,false,false,false,2,0,false));Assert.False(CustodyRules.Surrender(true,true,false,true,false,false,false,2,0,true));Assert.False(CustodyRules.Surrender(true,true,true,false,false,false,false,2,0,true));Assert.False(CustodyRules.Surrender(true,true,true,true,true,false,false,2,0,true));Assert.False(CustodyRules.Surrender(true,true,true,true,false,false,true,2,0,true));Assert.False(CustodyRules.Surrender(true,true,true,true,false,false,false,2,float.NaN,true));Assert.False(CustodyRules.Surrender(true,true,true,true,false,false,false,2,.5f,true));}
        [Fact] public void InvalidConfigDoesNotBook(){var w=Book();CustodyTransactions.Release(w,"case",true,()=>{},out _);var c=Options();c.SecondsPerStar=0;Assert.False(c.Valid);Assert.False(CustodyTransactions.Book(w,"other",2,c,()=>throw new Exception(),out _));c=Options();c.Radius=float.NaN;Assert.False(c.Valid);c=Options();c.Cell=null;Assert.False(c.Valid);}
        [Fact] public void ExclusiveGateProtectsAllJobsAndTraffic(){var g=new ShiftGate();Assert.True(g.Acquire("custody"));Assert.False(g.Acquire("traffic"));Assert.False(g.Acquire("pilot"));g.Release("traffic");Assert.Equal("custody",g.Owner);g.Release("custody");Assert.True(g.Acquire("pizza"));}
    }
}
